result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "apidoc_diff.py", "content": "#!/usr/bin/env python3
"""Public-API change detector.

Parses two versions of a Python module with ``ast`` and reports
API-breaking changes between them:

* removed public functions/classes            -> BREAKING
* added required parameters                   -> BREAKING
* removed parameters                          -> BREAKING
* parameter default changes                   -> NON-BREAKING ('changed')
* added optional parameters                   -> NON-BREAKING ('added optional')

Usage::

    python apidoc_diff.py v1.py v2.py

Exits 1 iff breaking changes exist, 0 otherwise.
"""

from __future__ import annotations

import argparse
import ast
import sys
from dataclasses import dataclass, field


@dataclass(frozen=True)
class Param:
    """A single function parameter."""

    name: str
    has_default: bool


@dataclass
class FunctionAPI:
    params: list[Param] = field(default_factory=list)
    has_vararg: bool = False
    has_kwarg: bool = False


@dataclass
class APIMap:
    """Public API surface of a module."""

    functions: dict[str, FunctionAPI] = field(default_factory=dict)
    classes: set[str] = field(default_factory=set)


def _params_from_arguments(args: ast.arguments) -> FunctionAPI:
    """Build a FunctionAPI from an ``ast.arguments`` node."""
    positional = list(getattr(args, "posonlyargs", [])) + list(args.args)
    defaults = list(args.defaults)
    # `defaults` lines up with the tail of the positional parameters.
    n_without = len(positional) - len(defaults)
    has_default = [False] * n_without + [True] * len(defaults)

    params = [Param(name=a.arg, has_default=d) for a, d in zip(positional, has_default)]

    kwonly_has_default = {True} * 0  # placeholder, filled below
    kwonly_has_default = set()
    for a, d in zip(args.kwonlyargs, args.kw_defaults):
        kwonly_has_default.add(a.arg)
        params.append(Param(name=a.arg, has_default=d is not None))

    return FunctionAPI(
        params=params,
        has_vararg=args.vararg is not None,
        has_kwarg=args.kwarg is not None,
    )


def extract_api(source: str) -> APIMap:
    """Extract the public API (no leading underscore) of a module."""
    tree = ast.parse(source)
    api = APIMap()

    def is_public(name: str) -> bool:
        return not name.startswith("_")

    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and is_public(node.name):
            api.functions[node.name] = _params_from_arguments(node.args)
        elif isinstance(node, ast.ClassDef) and is_public(node.name):
            api.classes.add(node.name)

    return api


def compare_apis(old: APIMap, new: APIMap) -> tuple[list[str], list[str]]:
    """Compare two API maps.

    Returns ``(breaking, non_breaking)`` lists of human-readable findings.
    """
    breaking: list[str] = []
    non_breaking: list[str] = []

    # --- Removed / changed classes -------------------------------------
    for name in sorted(old.classes - new.classes):
        breaking.append(f"removed public class '{name}'")

    # --- Added classes are non-breaking ---------------------------------
    for name in sorted(new.classes - old.classes):
        non_breaking.append(f"added public class '{name}'")

    # --- Removed / changed functions ------------------------------------
    for name in sorted(set(old.functions) - set(new.functions)):
        breaking.append(f"removed public function '{name}'")

    for name in sorted(set(new.functions) - set(old.functions)):
        fn = new.functions[name]
        all_optional = all(p.has_default for p in fn.params)
        kind = "optional" if all_optional else "required"
        if all_optional:
            non_breaking.append(f"added public function '{name}' (all params optional)")
        else:
            breaking.append(f"added public function '{name}' with required parameters")
        del kind

    # --- Functions present in both versions ------------------------------
    for name in sorted(set(old.functions) & set(new.functions)):
        old_fn, new_fn = old.functions[name], new.functions[name]
        old_params = {p.name: p.has_default for p in old_fn.params}
        new_params = {p.name: p.has_default for p in new_fn.params}

        # Added parameters
        added = [p for p in new_fn.params if p.name not in old_params]
        for p in added:
            if p.has_default:
                non_breaking.append(f"added optional parameter '{p.name}' to '{name}()'") 
            else:
                breaking.append(f"added required parameter '{p.name}' to '{name}()'")

        # Removed parameters
        for p_name in old_params:
            if p_name not in new_params:
                breaking.append(f"removed parameter '{p_name}' from '{name}()'")

        # Default-value changes on surviving parameters
        for p in old_fn.params:
            if p.name in new_params and p.has_default != new_params[p.name]:
                non_breaking.append(f"changed default of parameter '{p.name}' in '{name}()'")

    return breaking, non_breaking


def diff_files(path_old: str, path_new: str) -> tuple[list[str], list[str]]:
    with open(path_old, encoding="utf-8") as f:
        old_api = extract_api(f.read())
    with open(path_new, encoding="utf-8") as f:
        new_api = extract_api(f.read())
    return compare_apis(old_api, new_api)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Detect public-API breaking changes.")
    parser.add_argument("old", help="path to the old version of the module")
    parser.add_argument("new", help="path to the new version of the module")
    ns = parser.parse_args(argv)

    breaking, non_breaking = diff_files(ns.old, ns.new)

    if breaking:
        print("BREAKING:")
        for item in breaking:
            print(f"  - {item}")
    else:
        print("BREAKING:")
        print("  (none)")

    print()
    if non_breaking:
        print("NON-BREAKING:")
        for item in non_breaking:
            print(f"  - {item}")
    else:
        print("NON-BREAKING:")
        print("  (none)")

    return 1 if breaking else 0


if __name__ == "__main__":
    sys.exit(main())
"})
